import React, { useState } from 'react';

const PropertyTabs = ({ property }) => {
  const [activeTab, setActiveTab] = useState('description');

  const tabs = [
    { id: 'description', label: 'Description' },
    { id: 'floorPlan', label: 'Floor Plan' },
    { id: 'map', label: 'Location' }
  ];

  return (
    <div className="property-tabs-container">
      <div className="tabs-header">
        {tabs.map(tab => (
          <button
            key={tab.id}
            className={`tab-btn ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      
      <div className="tab-content">
        {activeTab === 'description' && (
          <div className="description-content">
            <div dangerouslySetInnerHTML={{ __html: property.longDescription }} />
            <div className="features-list">
              <h4>Property Features</h4>
              <div className="features-grid">
                {property.features.map((feature, index) => (
                  <div key={index} className="feature-item">
                    <span className="feature-icon">✓</span>
                    <span>{feature}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
        
        {activeTab === 'floorPlan' && (
          <div className="floorplan-content">
            <div className="floorplan-image">
              <img 
                src={property.floorPlan} 
                alt={`Floor plan for ${property.title}`}
              />
              <div className="floorplan-info">
                <h4>Property Dimensions</h4>
                <ul>
                  <li>Total Area: {property.sqft} sqft</li>
                  <li>Bedrooms: {property.bedrooms}</li>
                  <li>Bathrooms: {property.bathrooms}</li>
                  <li>Property Type: {property.type}</li>
                </ul>
              </div>
            </div>
          </div>
        )}
        
        {activeTab === 'map' && (
          <div className="map-content">
            <div className="map-container">
              <iframe
                title={`Location of ${property.location}`}
                width="100%"
                height="400"
                frameBorder="0"
                style={{ border: 0 }}
                src={`https://www.google.com/maps/embed/v1/place?key=AIzaSyBFw0Qbyq9zTFTd-tUY6dZWTgaQzuU17R8&q=${property.coordinates.lat},${property.coordinates.lng}&zoom=15`}
                allowFullScreen
              ></iframe>
            </div>
            <div className="location-info">
              <h4>Location Details</h4>
              <p><strong>Address:</strong> {property.location}</p>
              <p><strong>Transport:</strong> Excellent transport links nearby</p>
              <p><strong>Amenities:</strong> Schools, shops, restaurants within walking distance</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PropertyTabs;
